   for(const index of closed){const summary=reopened.locator('#toc details').nth(index).locator(':scope > summary');await summary.scrollIntoViewIfNeeded();const point=await summary.evaluate(e=>{const r=e.getBoundingClientRect();for(const dx of [-14,-10,-6,2,6,10,16,24,r.width-3]){const x=r.x+dx,y=r.y+r.height/2,hit=document.elementFromPoint(x,y);if(hit?.closest('summary')===e&&!hit.closest('a'))return{x,y}}return null});assert(point,'No accessible directory disclosure marker');await reopened.mouse.click(point.x,point.y)}
